const hubNames={calendar:'Personal learning calendar',discussions:'Course discussions',help:'Support requests'};
async function hubCall(action,data={}){const r=await fetch('/api/hub/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',kind:location.hash.slice(1),...data})});const result=await r.json();if(!r.ok)throw Error(result.error);return result;}
function hubPage(kind){return heading(hubNames[kind],'Local release · Saved in the tenant database')+`<section class="card prose"><p>${kind==='calendar'?'Personal events belong to your authenticated pilot account. These do not change academic deadlines.':kind==='discussions'?'Contributions are visible to active members of AIM310 in this tenant.':'Requests are visible to you and the course instructor. External support notifications are not connected.'}</p><button id="hub-refresh" class="button secondary">Refresh</button><div id="hub-status" role="status"></div></section><section class="card prose"><h2>${kind==='calendar'?'Add event':kind==='help'?'Create support request':'Start a discussion'}</h2><form id="hub-create"><label>Title<input name="title" required maxlength="150"></label>${kind==='calendar'?'<label>Date<input name="date" type="date" required></label>':''}<label>Details<textarea name="body" required maxlength="5000" rows="4"></textarea></label><button class="button">Save</button></form></section><section class="card prose"><h2>Saved records</h2><div id="hub-records">Connect to load your records.</div></section>`;}
async function hubLoad(){const d=await hubCall('list');document.getElementById('hub-status').textContent='Connected as '+d.user+' · '+d.role;document.getElementById('hub-records').innerHTML=d.records.map(r=>`<article class="callout"><h3>${esc(r.title)}</h3><p>${esc(r.event_date)} · ${esc(r.owner)} · ${esc(r.state)}</p><p style="white-space:pre-wrap">${esc(r.body)}</p>${r.owner===d.user||location.hash==='#help'&&d.role==='instructor'?`<button class="button secondary" data-hub-id="${r.id}" data-version="${r.version}" data-restore="${r.state==='archived'}">${r.state==='archived'?'Restore':'Archive'}</button>`:''}</article>`).join('')||'<p>No saved records yet.</p>';}
const beforeOperationalHub=render;render=function(){const route=location.hash.slice(1);if(location.port==='4180'&&hubNames[route]){document.getElementById('app').innerHTML=integratedShell(route,hubPage(route),model.role);bind();if(governedToken)hubLoad().catch(e=>document.getElementById('hub-status').textContent=e.message);}else if(location.port==='4180'&&['assignments','grades'].includes(route)){document.getElementById('app').innerHTML=integratedShell(route,serverCoursePage(),model.role);bind();if(governedToken)loadServerCourse().catch(e=>document.getElementById('server-course-status').textContent=e.message);}else beforeOperationalHub();};
document.addEventListener('submit',async e=>{if(!['hub-connect','hub-create'].includes(e.target.id))return;e.preventDefault();const f=e.target,v=new FormData(f);try{if(f.id==='hub-connect'){governedToken=v.get('token');f.reset();}else{await hubCall('create',Object.fromEntries(v));f.reset();}await hubLoad();}catch(err){document.getElementById('hub-status').textContent=err.message;}});
document.addEventListener('click',async e=>{const t=e.target.closest('#hub-refresh,[data-hub-id]');if(!t)return;try{if(t.dataset.hubId)await hubCall('archive',{id:t.dataset.hubId,version:Number(t.dataset.version),restore:t.dataset.restore==='true'});await hubLoad();}catch(err){document.getElementById('hub-status').textContent=err.message;}});
render();
